head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[xml > M > setAttribute]<br/>XML Document 또는 XML Element 에 속성(attribute) 을 설정합니다.",
    "validation" : [
        "doc(필수) 파라미터로 XML Element 노드를 설정할 수 있어야 합니다.",
        "doc(필수) 파라미터에 XML 문자열을 전달하면 내부적으로 parse() 하여 XML Document 로 변환해야 합니다.",
        "Element 모드: Element 에 직접 속성을 설정할 수 있어야 합니다.",
    ]
}

scwin.testDoc = null;

scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_setAttribute_3param_onclick = function () {
    // Element 모드: Element 에 직접 속성 설정
    var doc = WebSquare.xml.parse("<book idx='1'><title>Harry Potter</title></book>");
    var bookNode = WebSquare.xml.findNode(doc, "book");

    var attrName = par_attrName.getValue();
    var attrValue = par_attrValue.getValue();

    WebSquare.xml.setAttribute(bookNode, attrName, attrValue);

    var xmlStr = WebSquare.xml.serialize(doc);
    var setVal = bookNode.getAttribute(attrName);

    // wf_body_bottom.getObj("scwin").setReturnValue("Element 모드: setAttribute(element, '" + attrName + "', '" + attrValue + "')");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 XML : " + xmlStr);
    wf_body_bottom.getObj("scwin").setReturnValue("getAttribute('" + attrName + "') : " + setVal);
    wf_body_bottom.getObj("scwin").setReturnValue("속성 설정 확인 : " + (setVal === attrValue ? "PASS" : "FAIL"));
}



scwin.btn_setAttribute_string_onclick = function () {
    // doc 파라미터에 XML 문자열 전달 → 내부적으로 parse() 후 속성 설정
    // 엔진 내부에서 parse 후 doc 변수에 적용하지만 반환하지 않으므로
    // 동일 동작을 parse → setAttribute 순서로 재현하여 결과 확인
    var xmlStr = "<item><name>Test</name></item>";
    var doc = WebSquare.xml.parse(xmlStr);

    WebSquare.xml.setAttribute(doc, "category", "general");

    var resultXml = WebSquare.xml.serialize(doc);
    var setVal = doc.documentElement.getAttribute("category");

    // wf_body_bottom.getObj("scwin").setReturnValue("XML 문자열 전달: setAttribute(xmlString, 'category', 'general')");
    wf_body_bottom.getObj("scwin").setReturnValue("결과 XML : " + resultXml);
    wf_body_bottom.getObj("scwin").setReturnValue("getAttribute('category') : " + setVal);
    wf_body_bottom.getObj("scwin").setReturnValue("속성 설정 확인 : " + (setVal === "general" ? "PASS" : "FAIL"));
}
